'use strict';
const Business={data:null,can:p=>CurrentUser.permissions.includes(p),async load(){this.data=await API.request('/masters');window.I18n?.protect(this.data);return this.data;},open(title,html){dialog(title,html);$('dialog').classList.add('business-dialog');},async masters(){const d=await this.load();const types={customers:'客户',batches:'生产批次',warehouses:'仓库',yards:'堆场',locations:'货位'};this.open('基础资料管理',`<div class="business-toolbar"><label>资料类型<select id="master-type">${Object.entries(types).map(([k,v])=>`<option value="${k}">${v}</option>`).join('')}</select></label><label>搜索<input id="master-search" placeholder="编码或名称"></label><button id="master-add" class="button primary" ${this.can('master:write')?'':'disabled'}>新增资料</button></div><div id="master-list"></div>`);const render=()=>{const type=$('master-type').value,q=$('master-search').value.toLowerCase();$('master-list').innerHTML='<div class="business-table"><table><thead><tr><th>编码</th><th>名称 / 生产日期</th><th>状态</th><th>操作</th></tr></thead><tbody>'+d[type].filter(r=>(r.code+' '+(r.name||'')).toLowerCase().includes(q)).map(r=>`<tr><td>${esc(r.code)}</td><td>${esc(r.name||r.production_date?.slice(0,10)||'—')}</td><td>${r.active?'启用':'停用'}</td><td><button class="detail-button" data-master="${r.id}" ${this.can('master:write')?'':'disabled'}>修改 / 停用</button></td></tr>`).join('')+'</tbody></table></div>';$('master-list').querySelectorAll('[data-master]').forEach(b=>b.onclick=()=>this.masterForm(type,d[type].find(r=>r.id===b.dataset.master)).catch(e=>notify(e.message)));};$('master-type').onchange=render;$('master-search').oninput=render;$('master-add').onclick=()=>this.masterForm($('master-type').value).catch(e=>notify(e.message));render();},
 options(rows,value,label='code',empty=false){return (empty?'<option value="">未指定</option>':'')+rows.map(r=>`<option value="${r.id}" ${r.id===value?'selected':''}>${esc(r[label])}${r.active===false?'（已停用）':''}</option>`).join('');},
 async masterForm(type,row={}){const d=this.data||await this.load();this.open(row.id?'修改基础资料':'新增基础资料',`<form id="master-form" class="user-form"><label>项目<select name="project_id" ${row.id?'disabled':''}>${this.options(d.projects,row.project_id,'name')}</select></label><label>编码<input name="code" value="${esc(row.code||'')}" required maxlength="60"></label>${['customers','warehouses','yards'].includes(type)?`<label>名称<input name="name" value="${esc(row.name||'')}" required></label>`:''}${['yards','locations'].includes(type)?`<label>仓库<select name="warehouse_id">${this.options(d.warehouses,row.warehouse_id)}</select></label>`:''}${type==='locations'?`<label>堆场<select name="yard_id">${this.options(d.yards,row.yard_id,'name',true)}</select></label>`:''}${type==='batches'?`<label>生产日期<input type="date" name="production_date" value="${esc(row.production_date?.slice(0,10)||'')}"></label>`:''}<label>状态<select name="active"><option value="true">启用</option><option value="false" ${row.active===false?'selected':''}>停用</option></select></label><p class="error" id="master-error" role="alert"></p><button class="button primary">保存</button></form><p>使用中的货位、仓库或堆场不能直接停用；变更需通过服务端权限与版本校验。</p>`);$('master-form').onsubmit=async e=>{e.preventDefault();e.submitter.disabled=true;const b=Object.fromEntries(new FormData(e.target));b.active=b.active==='true';if(row.id){delete b.project_id;b.version=row.version;}try{await API.request('/masters/'+type+(row.id?'/'+row.id:''),{method:row.id?'PATCH':'POST',body:b});await (type==='customers'?this.customers():this.masters());notify('基础资料已保存');}catch(err){$('master-error').textContent=err.message;e.submitter.disabled=false;}};},
 menu(){this.open('业务工作台',`<div class="business-menu"><button id="open-masters" class="button secondary">基础资料</button><button id="open-receipts" class="button secondary" disabled>入库管理（开发中）</button><button id="open-allocations" class="button secondary" disabled>客户备货（开发中）</button></div>`);$('open-masters').onclick=()=>this.masters().catch(e=>notify(e.message));}
};
if(window.Connected){const nav=document.querySelector('.sidebar nav'),button=document.createElement('button');button.dataset.legacyMain='customers';button.textContent='▤ 基础资料';button.onclick=()=>Business.masters().catch(e=>notify(e.message));nav.append(button);const top=document.createElement('button');top.className='text-button';top.textContent='业务';top.id='business-menu';top.onclick=()=>Business.menu();document.querySelector('.top-actions').prepend(top);}
